INSERT INTO `listas` (`id_lista`, `id_usuario`, `titulo`, `descripcion`, `imagen`, `fecha_creacion`, `visibilidad`) VALUES
(1, 1, 'Para morir de risa', 'Las películas que me han hecho reír a lo largo de los años. Comedias imprescindibles para desconectar y disfrutar.', 'https://image.tmdb.org/t/p/original/v7Vpqyepu54v0chKrbLECYfg8Vk.jpg', '2026-04-07 11:55:31', 'publica'),
(2, 2, 'Clásicos que no puedes perderte', 'Películas esenciales que todo amante del cine debería ver al menos una vez en la vida.', 'https://wearekikazaru.com/wp-content/uploads/2021/09/image.jpeg', '2026-04-07 12:48:46', 'publica'),
(3, 1, 'Joyas de animación', 'Historias animadas que van mucho más allá de lo infantil. Arte, emoción y narrativa en estado puro.', 'https://i0.wp.com/elgeneracionalpost.com/wp-content/uploads/2024/10/01.jpg?fit=696%2C294&ssl=1', '2026-04-07 12:48:46', 'privada'),
(4, 1, 'Para soltar alguna lágrima', 'Si necesitas una lloradita, estas películas te van a tocar la fibra.', 'https://cloudfront-us-east-1.images.arcpublishing.com/copesa/ZVSGRLTVTBHH5D6VJWK2CSL3PI.jpg', '2026-04-07 12:48:46', 'publica'),
(5, 2, 'Thrillers que te vuelan la cabeza', 'Películas con giros inesperados, tensión constante y finales que no olvidarás.', 'https://imagenes.20minutos.es/files/image_640_auto/uploads/imagenes/2021/07/08/memento.jpeg', '2026-04-07 12:48:46', 'publica'),
(6, 1, 'Cine con alma', 'Películas fuera del circuito comercial que destacan por su originalidad y narrativa.', 'https://www.indiewire.com/wp-content/uploads/2020/04/the-florida-project-lead.png', '2026-04-07 12:48:46', 'publica'),
(7, 1, 'Spooky Season', 'Perfectas para Halloween o para una noche de terror.', 'https://i.pinimg.com/564x/fa/86/8f/fa868f08fb1908ecb7af23350f5dee76.jpg', '2026-04-07 12:48:46', 'publica'),
(11, 4, 'Dibujitos monos', 'Esta es una lista de dibujitos', 'https://i.blogs.es/4b7078/650_1000_nemo1/650_1200.jpg', '2026-04-12 15:00:11', 'publica'),
(12, 1, 'Lista de prueba', 'Esta lista es de prueba', 'img/lista-default.jpg', '2026-05-04 12:29:33', 'publica');
