INSERT INTO `noticias` (`id_noticia`, `titulo`, `descripcion`, `contenido`, `imagen`, `autor`, `fecha`, `id_usuario`) VALUES
(1, '\'The Batman Part II\': todo lo que sabemos del regreso de Pattinson.', 'Matt Reeves retoma su épica saga criminal de Gotham con una secuela que promete ser \"muy diferente\" y arrancar el rodaje en Londres en junio de 2026.', 'Warner Bros. tiene fecha: el 1 de octubre de 2027 llegará a los cines The Batman Part II, la esperada secuela de Matt Reeves que continuará la historia de Robert Pattinson como Bruce Wayne. Tras años de retrasos provocados por la huelga de guionistas y actores de Hollywood, el proyecto ha recuperado por fin un calendario firme de producción.\r\n\r\nEl guión que lo cambia todo\r\n\r\nEl propio Pattinson ha roto su habitual hermetismo para compartir su entusiasmo con la película. En declaraciones recogidas por Deadline en marzo de 2026, el actor ha asegurado que la secuela va a ser \"muy, muy especial y muy diferente\", y que el guion \"se está arriesgando en grande\".\r\n\r\nColin Farrell, que da vida al Pingüino, ha sido igualmente elogioso con el trabajo de Reeves: ha calificado el guion de \"obra maestra contemporánea del género\", destacando que es denso, inteligente y profundo, y que el viaje que aguarda al personaje de Pattinson será extraordinario.\r\n\r\n[IMG:img/noticias/noticia-batman-1.jpg]\r\n\r\nUn rodaje en Londres\r\n\r\nEl rodaje comenzará en junio de 2026 en Londres, según ha confirmado Deadline. La producción contará con el regreso de los actores principales: además de Pattinson y Farrell, Andy Serkis retomará su papel como Alfred Pennyworth tras resolver el conflicto de agenda con el rodaje de El señor de los anillos: La caza de Gollum. Jeffrey Wright también repite como el teniente Jim Gordon.\r\n\r\nIncorporaciones de peso al reparto\r\n\r\nLas novedades en el reparto apuntan a fichajes de primer nivel. Scarlett Johansson negocia un papel aún no desvelado, mientras que Sebastian Stan está en conversaciones para unirse al proyecto. Los rumores sobre el villano principal apuntan a Harvey Dent como figura central, aunque el estudio no ha confirmado ningún nombre para ese rol.\r\n\r\n[IMG:img/noticias/noticia-batman-2.jpg]\r\n\r\nUna trilogía con identidad propia\r\n\r\nLa película se enmarca en el universo propio de Reeves, The Batman Epic Crime Saga, al margen del DCU de James Gunn. El director ha dejado claro que su intención es completar una trilogía, y que esta segunda entrega construirá directamente sobre el colapso de Gotham y la evolución de Bruce Wayne tras los eventos de la primera película y la serie The Penguin de HBO.\r\n\r\nCon un primer film que recaudó más de 772 millones de dólares en todo el mundo, las expectativas para la secuela son enormes. Aunque el tráiler oficial no se espera hasta principios de 2027, la avalancha de noticias sobre el casting y las declaraciones del reparto mantienen el interés de los fans en su punto más alto.', 'img/noticias/batman2.jpg', 'Redacción TakeOne', '2026-04-17 09:00:00', 3),
(2, 'Cannes 2026: las películas más esperadas de la selección oficial', 'El festival más prestigioso del mundo desvela su cartel: autores consagrados, debuts explosivos y una edición que promete sacudir el año cinematográfico.', 'El Festival de Cannes 2026 ha presentado su selección oficial y, como cada año, la lista ha despertado tanto entusiasmo como debate. La edición, que se celebrará entre el 13 y el 24 de mayo, reúne a algunos de los cineastas más relevantes del panorama internacional junto a voces emergentes que llegan dispuestas a sorprender.\r\n\r\nLos grandes nombres de la competición\r\n\r\nPaul Thomas Anderson regresa a la Croisette con una película ambientada en el mundo del jazz de los años sesenta, protagonizada por Denzel Washington y Zendaya. El proyecto lleva años en desarrollo y su inclusión en la competición oficial confirma que la espera ha valido la pena. Por su parte, la directora francesa Mia Hansen-Løve presenta una nueva obra de marcado carácter autobiográfico, mientras que el cineasta coreano Park Chan-wook compite con un thriller psicológico que promete revisitar los temas que le consagraron internacionalmente.\r\n\r\n[IMG:img/noticias/noticia-cannes-1.png]\r\n\r\nEl cine latinoamericano, protagonista\r\n\r\nUna de las noticias más celebradas ha sido la presencia de tres películas latinoamericanas en secciones de peso. La directora argentina Lucía Puenzo lleva su último largometraje a la sección Un Certain Regard, mientras que el mexicano Carlos Reygadas compite por la Palma de Oro con una obra que, según los primeros rumores, supone un giro radical en su filmografía.\r\n\r\nLa sección oficial de documentales también destaca especialmente este año, con trabajos sobre la crisis climática, la inteligencia artificial y el conflicto en Oriente Próximo que han generado considerable expectación antes incluso de su estreno en el palacio de festivales.\r\n\r\n[IMG:img/noticias/noticia-cannes-2.jpg]\r\n\r\nEl palmarés, el 24 de mayo\r\n\r\nEl jurado estará presidido por la actriz y directora Cate Blanchett, que regresa a Cannes en una faceta diferente a la de años anteriores. Los premios se entregarán el 24 de mayo en una ceremonia de clausura que se espera multitudinaria. TakeOne seguirá todas las proyecciones y ofrecerá cobertura completa desde la Croisette.', 'img/noticias/cannes.png', 'Redacción TakeOne', '2026-04-15 10:00:00', 3),
(3, 'Marvel redefine su estrategia tras el descenso en taquilla: menos películas, más calidad y un universo más cohesionado', 'La compañía reorganiza su calendario de lanzamientos y apuesta por historias más conectadas, personajes mejor desarrollados y el fin de la saturación que alejó al público en los últimos años.', 'Tras varios estrenos con resultados por debajo de lo esperado, Marvel Studios ha decidido replantear en profundidad su estrategia de lanzamientos. El cambio no es cosmético: afecta al número de proyectos anuales, a la forma en que se desarrollan los guiones y a la relación entre el cine y las series de la plataforma.\r\n\r\nMenos es más: el nuevo calendario\r\n\r\nDurante los años de mayor actividad del UCM, el estudio llegó a estrenar hasta cuatro películas y cinco series en un mismo año. El resultado fue la saturación de un público que dejó de sentir cada estreno como un acontecimiento. El propio CEO de Disney, Bob Iger, reconoció públicamente que la compañía había priorizado la cantidad sobre la calidad, y anunció un giro radical: de cara al futuro, Marvel no superará las dos o tres películas anuales, acompañadas de un máximo de dos series. El objetivo es que cada proyecto tenga el tiempo y los recursos necesarios para estar a la altura de las expectativas.\r\n\r\n[IMG:img/noticias/noticia-marvel-1.jpg]\r\n\r\nNarrativas más sólidas y personajes mejor construidos\r\n\r\nEl otro gran eje del cambio es narrativo. Marvel ha apostado por recuperar a los hermanos Anthony y Joe Russo en la dirección de Vengadores: Doomsday, y por contar con guionistas de la talla de Michael Waldron y Stephen McFeely para garantizar una historia a la altura del cierre de la Saga del Multiverso. La nueva hoja de ruta huye de los proyectos puente, aquellos diseñados únicamente para conectar tramas, y apuesta por películas y series que funcionen de forma autónoma sin renunciar a la coherencia del universo compartido. Títulos recientes como Thunderbolts* o Los 4 Fantásticos: Primeros Pasos han demostrado que el modelo puede funcionar cuando se le da el espacio necesario.\r\n\r\n[IMG:img/noticias/noticias-marvel-2.jpg]\r\n\r\nUn punto de inflexión de cara a la Fase Seis\r\n\r\nEl gran examen de esta nueva estrategia llegará el 18 de diciembre de 2026 con el estreno de Vengadores: Doomsday, la película número 40 del UCM y la primera de las dos entregas que cierran la Fase Seis. Si los números acompañan, Marvel habrá demostrado que sabe reinventarse. Si no, la presión sobre Secret Wars, prevista para diciembre de 2027, será enorme. Por ahora, la industria observa con atención un giro que puede marcar el futuro no solo del estudio, sino del cine de superhéroes en general.', 'img/noticias/marvel.jpg', 'Redacción TakeOne', '2026-04-14 11:30:00', 3),
(4, 'La inteligencia artificial en el cine: herramienta creativa o amenaza para los oficios', 'Directores, actores y técnicos debaten sobre el impacto real de la IA generativa en la producción cinematográfica, un año después de los acuerdos sindicales de Hollywood.', 'Un año después de que los sindicatos de guionistas y actores de Hollywood alcanzasen acuerdos con los grandes estudios sobre el uso de la inteligencia artificial, el sector hace balance. Los resultados son tan dispares como las posiciones que existían antes de los pactos: para unos la IA se ha convertido en un aliado eficaz en tareas concretas; para otros, la amenaza sobre ciertos oficios es más real que nunca.\r\n\r\nLo que la IA ya hace en los rodajes\r\n\r\nEn la fase de preproducción, herramientas de generación de imágenes permiten crear storyboards y visualizaciones de escenas en cuestión de horas, un proceso que antes requería días de trabajo de ilustradores. En posproducción, los programas de limpieza de imagen y eliminación de elementos del fondo han reducido drásticamente los tiempos de trabajo en efectos visuales. Algunos directores de fotografía han comenzado a usar modelos de IA para simular esquemas de iluminación antes de llegar al set.\r\n\r\n[IMG:img/noticias/noticia-ia-1.jpg]\r\n\r\nLas fronteras que siguen en disputa\r\n\r\nDonde el debate se endurece es en la escritura y en la actuación digital. Los acuerdos sindicales prohíben utilizar la IA para generar guiones sin supervisión humana acreditada y exigen el consentimiento explícito de los actores para replicar digitalmente su voz o imagen. Sin embargo, varios estudios medianos han encontrado resquicios interpretativos que los sindicatos están impugnando judicialmente.\r\n\r\nDirectores como Rian Johnson han declarado públicamente que no usan IA en ninguna fase de su proceso creativo, mientras que realizadores de efectos visuales como los equipos de Wētā FX defienden que la integración de herramientas de aprendizaje automático es inevitable y necesaria para mantener la competitividad del sector.\r\n\r\n[IMG:img/noticias/noticia-ia-2.jpg]\r\n\r\nUna industria en redefinición\r\n\r\nLo que parece claro es que la industria está en un proceso de redefinición acelerado. Los oficios más expuestos a la automatización son los de efectos visuales de nivel medio y ciertos trabajos de postproducción de audio. Los roles creativos de alto nivel y el trabajo en set parecen más protegidos, al menos por el momento. El debate, lejos de cerrarse, se intensificará a medida que la tecnología siga avanzando.', 'img/noticias/noticia-ia.png', 'Redacción TakeOne', '2026-04-16 09:00:00', 3),
(5, 'Carolina Yuste: «Faltan relatos sobre qué significó ser adolescente durante los 2000 en las provincias»', 'La actriz extremeña, ganadora de dos premios Goya, reflexiona sobre el cine español, la memoria de una generación y el oficio de interpretar en las Jornadas del Oficio Cinematográfico de Las Palmas de Gran Canaria.', 'Carolina Yuste (Badajoz, 1991) llegó al mundo de la interpretación casi por accidente y se quedó porque, según ella misma ha contado, al pisar el escenario por primera vez descubrió algo que «engancha». Desde entonces ha acumulado dos premios Goya —mejor actriz de reparto por Carmen y Lola en 2019 y mejor actriz protagonista por La infiltrada en 2025— y se ha convertido en uno de los nombres más sólidos del cine español de su generación. Esta semana participó en las Jornadas del Oficio Cinematográfico, organizadas en el marco del Festival Internacional de Cine de Las Palmas de Gran Canaria.\r\n\r\nLa memoria de una generación sin relatos\r\n\r\nEn el coloquio, celebrado en la Sala de Cámara del Auditorio Alfredo Kraus y moderado por el periodista cultural Carlos del Amor, Yuste compartió reflexiones sobre los vacíos narrativos que aún persisten en el cine español. «Faltan relatos sobre qué significó ser adolescente durante los 2000 en las provincias», afirmó ante un auditorio lleno. La actriz, que creció en Badajoz, habló de cómo esa experiencia —alejada de los grandes centros culturales y marcada por una transición generacional acelerada— apenas ha sido retratada en la pantalla. «Hay toda una forma de crecer, de relacionarse, de entender el mundo que todavía no hemos contado», añadió.\r\n\r\n[IMG:img/noticias/noticia-carolina-1.jpg]\r\n\r\nEl oficio de interpretar y la incertidumbre como constante\r\n\r\nJunto a Nathalie Poza, Bárbara Lennie y Javier Gutiérrez —los cuatro intérpretes suman siete premios Goya—, Yuste habló también de los sacrificios que implica la profesión. «Para mí, mi oficio es el mejor. Me enriquece y me abre el pecho y el alma a niveles enormes. Pero a veces te exige mucho», reconoció. Sobre la incertidumbre laboral que acompaña a los actores, fue directa: «Hay que aprender a vivir con ella de manera habitual. Yo pienso que podría vivir de cualquier otra cosa y eso me ayuda». A la hora de elegir proyectos, explicó que lo decisivo para ella es siempre la historia: «Lo más importante es la historia que se quiera contar al mundo y luego la gente con la que se vaya a hacer».\r\n\r\n[IMG:img/noticias/noticia-carolina-2.jpg]\r\n\r\nUna voz necesaria en el cine español\r\n\r\nLas Jornadas del Oficio Cinematográfico, organizadas por la productora 18 Chulos con el apoyo del Ayuntamiento de Las Palmas de Gran Canaria, se han consolidado como una de las citas paralelas más esperadas del festival. En esta edición, el encuentro reunió a cuatro intérpretes de distintas generaciones para reflexionar sobre la esencia del trabajo actoral. Carolina Yuste, que en 2025 también codirigió su primer largometraje documental, Este cuerpo mío, junto a Afioco Gnecco, demostró una vez más que su figura trasciende la interpretación y que tiene mucho que decir, dentro y fuera de la pantalla.', 'img/noticias/carolina-yuste.jpeg', 'Redacción TakeOne', '2026-04-12 14:00:00', 3),
(6, 'El renacimiento del western: cómo el género más americano vuelve a dominar las pantallas', 'Tras años de ostracismo, el western experimenta un revival inesperado impulsado por plataformas, nuevas voces y una revisión profunda de sus mitos fundacionales.', 'Hace una década, decir que el western estaba muerto era una obviedad. Hoy, el género que nació con el propio cine y definió el imaginario de un país acumula estrenos, premios y audiencias millonarias en un revival que nadie anticipó con tanta fuerza.\r\n\r\nLas plataformas como motor del cambio\r\n\r\nEl primer impulso llegó de la televisión. Yellowstone y sus derivados demostraron que había un público masivo con hambre de historias ambientadas en el Oeste americano, siempre que estas actualizaran los conflictos del género hacia territorios contemporáneos: la especulación inmobiliaria, la lucha entre comunidades indígenas y rancheros, la crisis de identidad de una masculinidad en transformación. Las plataformas de streaming recogieron el testigo y comenzaron a producir largometrajes que revisitaban el western desde perspectivas hasta ahora marginales.\r\n\r\n[IMG:img/noticias/noticia-western-1.jpg]\r\n\r\nNuevas voces, nuevos héroes\r\n\r\nAlgunas de las películas western más celebradas de los últimos dos años tienen como protagonistas a mujeres, a personajes afroamericanos, asiáticos o indígenas que antes solo aparecían como figuras secundarias o estereotipadas. Directoras como Kelly Reichardt y Chloé Zhao han demostrado que el género puede acoger sensibilidades muy distintas sin perder su identidad narrativa esencial.\r\n\r\nEl western clásico de acción y duelos también tiene su momento, con títulos que recuperan la estética Sergio Leone sin nostalgia impostada. La clave parece estar en tomar en serio los valores formales del género, su relación con el paisaje, su ritmo pausado y su tendencia a lo épico, sin asumir automáticamente su bagaje ideológico más problemático.\r\n\r\n[IMG:img/noticias/noticia-western-2.jpg]\r\n\r\nUn género con mucho que decir\r\n\r\nLo que el western actual tiene en común con sus mejores momentos históricos es la capacidad para hablar del presente usando el pasado como distancia. La frontera, el conflicto por la tierra y la ley, la violencia y sus consecuencias: estas historias no han envejecido porque sus contradicciones tampoco lo han hecho. El género ha vuelto porque tenía cosas que decir, no porque haya pasado de moda.', 'img/noticias/western.png', 'Redacción TakeOne', '2026-04-15 10:30:00', 3),
(7, 'Las mejores películas españolas de la historia: un repaso imprescindible al cine de nuestro país', 'Desde los clásicos de Berlanga y Buñuel hasta las obras más recientes de Almodóvar o Arantxa Echevarría, el cine español ha dado al mundo títulos que resisten el paso del tiempo y merecen ser (re)descubiertos.', 'No es ningún secreto que España ocupa un lugar destacado en la historia del cine mundial. Es el tercer país con más premios Óscar a la mejor película internacional, solo superado por Francia e Italia. Sin embargo, muchas de sus obras maestras siguen siendo desconocidas para el gran público. Este repaso recoge algunos de los títulos que todo cinéfilo debería haber visto al menos una vez.\r\n\r\nLos pilares del cine clásico español\r\n\r\nCualquier lista seria tiene que empezar por Luis Buñuel y Luis García Berlanga, los dos gigantes que pusieron el cine español en el mapa internacional pese a las dificultades de la censura franquista. Viridiana (1961), de Buñuel, escandalizó al Vaticano y fue prohibida en España durante años, pero ganó la Palma de Oro en Cannes. El verdugo (1963), de Berlanga, con guion de Rafael Azcona, es una obra maestra de la comedia negra que se llevó el premio FIPRESCI en Venecia. A ellos se suma El espíritu de la colmena (1973), de Víctor Erice, considerada por muchos la mejor película española de todos los tiempos: una historia de posguerra narrada a través de los ojos de una niña que fue, además, una de las películas favoritas de Stanley Kubrick.\r\n\r\n[IMG:img/noticias/noticia-cine-espana-1.jpeg]\r\n\r\nLa explosión de los años ochenta y la generación Almodóvar\r\n\r\nCon la llegada de la democracia, el cine español vivió una renovación sin precedentes. Los santos inocentes (1984), de Mario Camus y basada en la novela de Miguel Delibes, fue elegida por los espectadores de RTVE como la mejor película española del siglo XX. En paralelo, Pedro Almodóvar reinventó el lenguaje cinematográfico del país con títulos como Mujeres al borde de un ataque de nervios (1988) o Todo sobre mi madre (1999), su primer Óscar. Fernando Trueba sumó otro Óscar con Belle Époque (1993), y Alejandro Amenábar consolidó el género de suspense español con Tesis (1996) y ganó otra estatuilla con Mar adentro (2004).\r\n\r\n[IMG:img/noticias/noticia-cine-espanol-2.jpeg]\r\n\r\nEl cine español hoy: una industria en plena forma\r\n\r\nLas últimas décadas han confirmado que el relevo generacional está garantizado. El laberinto del fauno (2006), de Guillermo del Toro, es hoy una referencia mundial del cine de autor fantástico. La habitación de al lado (2024), de Almodóvar, le valió al director su segundo Óscar. Y títulos más recientes como La infiltrada (2025), de Arantxa Echevarría, han demostrado que el cine español sigue siendo capaz de conectar con el gran público sin renunciar a la ambición narrativa. El mejor cine español no es solo historia: es un género vivo que sigue escribiendo sus mejores páginas.', 'img/noticias/noticia-cine-espana.jpeg', 'Redacción TakeOne', '2026-04-10 09:00:00', 3),
(8, 'El regreso del cine de autor en Hollywood: cuando los estudios apuestan por la visión personal', 'Un grupo de cineastas con control creativo total está demostrando que el cine de autor puede ser también negocio en la industria más comercial del mundo.', 'Durante años, la narrativa dominante fue que Hollywood había abandonado el cine de autor en favor de las franquicias y los universos expandidos. En 2026, esa narrativa necesita una revisión. Un grupo de directores con control creativo total sobre sus proyectos está demostrando que la industria más comercial del mundo tiene espacio, y negocio, para la visión personal.\r\n\r\nEl modelo que lo cambió todo\r\n\r\nEl punto de inflexión llegó con varios éxitos inesperados de películas de autor con presupuestos intermedios que superaron con creces las expectativas de taquilla. Barbie, Oppenheimer y Killers of the Flower Moon señalaron el camino: el público no rechaza el cine ambicioso, rechaza el cine aburrido. La diferencia entre un blockbuster genérico y una película con punto de vista autoral no es necesariamente de presupuesto, sino de convicción.\r\n\r\n[IMG:img/noticias/noticia-cine-autor-1.jpg]\r\n\r\nLos directores que lideran el cambio\r\n\r\nChristopher Nolan ha negociado con Universal un acuerdo de largo alcance que le garantiza control editorial absoluto sobre sus proyectos durante la próxima década. Wes Anderson tiene tres películas en desarrollo simultáneo con Netflix. Greta Gerwig desarrolla un proyecto animado original que ella misma describirá como la película más personal de su carrera. En todos estos casos, los estudios han aceptado condiciones que hace diez años habrían sido impensables: sin pruebas de audiencia vinculantes, sin notas de desarrollo obligatorias, sin decisiones de montaje por comité.\r\n\r\n[IMG:img/noticias/noticia-cine-autor-2.jpg]\r\n\r\nUn cambio estructural o una burbuja\r\n\r\nLa pregunta que recorre la industria es si este renacimiento del cine de autor en el mainstream es un cambio estructural o una burbuja que estallará con el primer fracaso importante. Los optimistas señalan que el público ha madurado y que las plataformas han educado el gusto hacia contenidos más complejos. Los escépticos recuerdan que Hollywood ya vivió ciclos similares en los años setenta y que la presión del mercado acabó con todos ellos. Por ahora, mientras los números acompañen, los estudios seguirán apostando por la visión personal.', 'img/noticias/cine-autor.png', 'Redacción TakeOne', '2026-04-09 11:00:00', 3),
(9, 'La princesa Mononoke: la obra maestra de Miyazaki que cambió la animación para siempre', 'Estrenada en 1997, la película de Studio Ghibli rompió todos los récords de taquilla en Japón, planteó una reflexión sin precedentes sobre el conflicto entre la naturaleza y el progreso, y consolidó a Hayao Miyazaki como uno de los grandes cineastas de la historia.', 'Cuando La princesa Mononoke se estrenó en Japón el 12 de julio de 1997, nadie esperaba lo que ocurrió. La película recaudó más de 160 millones de dólares y desbancó a E.T. como la cinta más taquillera de la historia del país, un récord que ostentaba desde 1983. Para Studio Ghibli y para Hayao Miyazaki, que había anunciado su retirada antes del estreno, supuso una consagración definitiva ante el mundo.\r\n\r\nUna historia entre la naturaleza y el progreso\r\n\r\nAmbientada en el Japón del período Muromachi, la película sigue al joven guerrero Ashitaka, maldito tras defender su aldea de un dios jabalí corrompido por el odio. Su viaje lo lleva al corazón de un bosque sagrado donde conviven dioses animales y la joven San —la princesa Mononoke—, criada por lobos, en guerra abierta contra los humanos que explotan sus recursos. Miyazaki no quiso retratar un Japón medieval preciso, sino capturar el inicio del conflicto entre la naturaleza y la civilización industrial moderna. La película se apoya en la mitología sintoísta —con sus kami, sus Kodama y sus dioses del bosque— para construir un relato donde ningún bando tiene razón absoluta y donde la codicia humana convive con la capacidad de redención.\r\n\r\n[IMG:img/noticias/noticia-princesa-mononoke-1.png]\r\n\r\nUna animación que no envejece\r\n\r\nLa princesa Mononoke fue el primer largometraje de Miyazaki en incorporar herramientas digitales, aunque de forma muy limitada: apenas 170 de sus más de 144.000 fotogramas fueron realizados por ordenador. El resultado es una animación que mezcla la precisión artesanal de Ghibli con paisajes de una belleza casi hipnótica, inspirados en los bosques de la isla de Yakushima. La banda sonora de Joe Hisaishi acompaña cada secuencia con una partitura que amplifica la épica y la melancolía del relato. Críticos y espectadores coinciden: a casi treinta años de su estreno, la película no ha perdido ni un gramo de su fuerza.\r\n\r\n[IMG:img/noticias/noticia-princesa-mononoke-2.jpg]\r\n\r\nEl legado de una obra sin igual\r\n\r\nLa princesa Mononoke es, para muchos, la película más desafiante e importante de toda la filmografía de Miyazaki. Con ella, el director volcó sus reflexiones sobre la historia, la crisis medioambiental y la dificultad de sobrevivir en un mundo contradictorio. La WWF la incluyó entre sus obras recomendadas por su mensaje ecologista. Y aunque El viaje de Chihiro acabaría superando sus cifras de taquilla años después, ninguna otra película de Ghibli ha vuelto a alcanzar la densidad temática y la ambición narrativa de esta historia de bosques, dioses y guerreros que todavía hoy sigue siendo una carta abierta del cineasta al mundo.', 'img/noticias/princesa-mononoke.jpg', 'Redacción TakeOne', '2026-04-08 10:00:00', 3),
(10, '\'Vengadores: Doomsday\' llega en diciembre con Robert Downey Jr. como villano y los hermanos Russo al mando', 'Marvel apuesta por su regreso más ambicioso: el UCM reúne a sus héroes más icónicos frente a la mayor amenaza del multiverso en la esperada quinta entrega de los Vengadores.', 'Después de varios años de un Marvel dividido entre series, proyectos de autor y blockbusters de resultado desigual, el estudio vuelve a la carga con su apuesta más grande desde Avengers: Endgame. Vengadores: Doomsday llega a los cines el 18 de diciembre de 2026 y promete ser el acontecimiento cinematográfico del año.\r\n\r\nDe qué va Vengadores: Doomsday\r\n\r\nLa película arranca donde el UCM nunca había llegado: el multiverso como campo de batalla total. Doctor Doom, encarnado por un sorprendente Robert Downey Jr. en un rol completamente distinto al de Tony Stark, emerge como la amenaza definitiva para todas las realidades conocidas. Vengadores, Wakandanos, los Cuatro Fantásticos, los Nuevos Vengadores y los X-Men convergen desde universos distintos para hacer frente a un enemigo que los supera a todos.\r\n\r\n[IMG:img/noticias/noticia-doomsday-1.png]\r\n\r\nUn reparto histórico para el UCM\r\n\r\nLa película reúne a Chris Hemsworth, Chris Evans —que regresa como Capitán América con uno de los giros más comentados del tráiler—, Pedro Pascal, Vanessa Kirby, Joseph Quinn y Anthony Mackie, entre muchos otros. El regreso de los hermanos Anthony y Joe Russo a la dirección, con guion de Michael Waldron y Stephen McFeely, ha devuelto la confianza al fandom tras años de resultados irregulares.\r\n\r\nEl rodaje arrancó en abril de 2025 en los Pinewood Studios de Inglaterra y finalizó en septiembre, con exteriores adicionales rodados en Baréin. Marvel y Disney han guardado la trama bajo un estricto secreto, aunque las primeras proyecciones en el CinemaCon de abril de 2026 generaron una respuesta entusiasta que ha vuelto a encender la expectación.\r\n\r\n[IMG:img/noticias/noticia-doomsday-2.jpg]\r\n\r\nEstreno y lo que viene después\r\n\r\nVengadores: Doomsday llegará a los cines el 18 de diciembre de 2026, distribuida por Walt Disney Studios. Será la película número 39 del UCM y la primera de las dos entregas que conforman la Fase Seis, ya que su secuela directa, Avengers: Secret Wars, está prevista para diciembre de 2027. Todo apunta a que Marvel se juega en estas dos películas el futuro entero de su universo cinematográfico.', 'img/noticias/doomsday-noticias.jpeg', 'Redacción TakeOne', '2026-04-07 09:30:00', 3),
(11, 'CinemaCon 2026: el primer tráiler de \'Vengadores: Doomsday\', \'Top Gun 3\' y todos los grandes anuncios del cine', 'Los grandes estudios de Hollywood presentaron sus apuestas más ambiciosas ante más de seis mil exhibidores de todo el mundo.', 'Del 13 al 16 de abril, el Caesars Palace de Las Vegas acogió una nueva edición de la CinemaCon, el evento anual donde Hollywood le muestra al mundo de la exhibición lo que tiene preparado para los próximos meses. La edición de 2026 ha sido una de las más comentadas en años, impulsada por el primer tráiler de Vengadores: Doomsday y una avalancha de anuncios que han encendido las redes sociales.\r\n\r\nEl momento del año: el tráiler de Vengadores: Doomsday\r\n\r\nDisney cerró el evento con la presentación más esperada. Marvel mostró nuevo metraje de Vengadores: Doomsday —dirigida por los hermanos Russo y protagonizada por Robert Downey Jr. como Doctor Doom— que dejó a los exhibidores en pie. Las imágenes incluyeron a Thor enfrentándose a Doctor Doom, el regreso de Steve Rogers y una secuencia con el Profesor X presenciando una incursión multiversal. También se confirmaron entradas a la venta para The Mandalorian y Grogu, y se mostraron avances de Toy Story 5 y la secuela de El diablo viste de Prada.\r\n\r\n[IMG:img/noticias/noticia-cinemacon-1.jpg]\r\n\r\nLos otros grandes anuncios por estudio\r\n\r\nParamount protagonizó otra de las presentaciones más aplaudidas. Tom Cruise confirmó su regreso para Top Gun 3, y el estudio también anunció Guerra Mundial Z 2 y Un lugar en silencio 3. El actor Johnny Depp vuelve a las grandes producciones con Ebenezer: A Christmas Carol. Sony, por su parte, mostró nuevo material de Spider-Man: Brand New Day con Tom Holland y confirmó que Spider-Man: Beyond the Spider-Verse avanza sin contratiempos. StudioCanal sorprendió con el anuncio de Paddington 4 en desarrollo, un reboot de Escape from New York y una adaptación de Pippi Långstrump en imagen real.\r\n\r\n[IMG:img/noticias/noticia-cinemacon-2.png]\r\n\r\nUna industria que apuesta por las salas\r\n\r\nMás allá de los títulos concretos, la CinemaCon 2026 dejó un mensaje claro: Hollywood sigue creyendo en la experiencia cinematográfica en sala frente al avance del streaming y la inteligencia artificial. Con más de seis mil profesionales llegados de más de sesenta países, el evento reafirmó su papel como el principal escaparate de la industria y anticipa un segundo semestre de 2026 cargado de grandes estrenos.', 'img/noticias/cinemacon.jpg', 'Redacción TakeOne', '2026-04-06 10:00:00', 3);
